export function MediaEmbed({
  title = "{{title}}",
  aspect = "{{aspect}}",
  radius = {{radius}},
  showPlayButton = {{showPlayButton}},
}) {
  return (
    <div style={{ position: "relative", maxWidth: 380, overflow: "hidden", background: "#241430",
      display: "flex", alignItems: "flex-end", aspectRatio: aspect, borderRadius: radius }}>
      <svg style={{ position: "absolute", inset: 0 }} viewBox="0 0 400 225" width="100%" height="100%" role="img" aria-label={`${title} — preview thumbnail`} preserveAspectRatio="xMidYMid slice">
        <rect width="400" height="225" fill="#241430" />
        <circle cx="120" cy="70" r="34" fill="#D9C8F0" />
        <rect x="0" y="170" width="400" height="55" fill="#24143080" />
      </svg>
      {/* Facade / "lite embed" pattern: only load the real third-party iframe once the button is
          activated, e.g. <iframe title={title} src="https://your-video-provider.example/embed/..." allowFullScreen /> */}
      {showPlayButton && (
        <button type="button" aria-label={`Play ${title}`}
          style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)",
            width: 52, height: 52, borderRadius: "50%", border: "none", background: "#FAF7F2",
            display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
          <svg viewBox="0 0 24 24" width={22} height={22} aria-hidden="true"><path d="M8 5v14l11-7z" fill="#241430" /></svg>
        </button>
      )}
      <p style={{ position: "relative", margin: 0, padding: "8px 12px", color: "#FAF7F2", font: "600 13px/1.4 system-ui, sans-serif" }}>{title}</p>
    </div>
  );
}
